#include <iostream>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    while (line.length() > 2 && line.substr(1, line.length() - 2).find("dot") != std::string::npos) {
        size_t dot_pos = line.find("dot", 1);
        if (dot_pos == std::string::npos) break;
        line.replace(dot_pos, 3, ".");
    }
    size_t at_pos = line.find("at", 1);
    if (at_pos != std::string::npos) {
        line.replace(at_pos, 2, "@");
    }
    std::cout << line << std::endl;
    return 0;
}
